SELECT k.name || ' — документов ' || (SELECT count(*) FROM project_documents d WHERE d.project_id = $1 AND d.entity_kind = k.name) || ', а чем вид становится в наборе не объявлено: ни своей таблицы, ни держателя чужих сущностей, ни «это проза»' AS detail FROM kind_layout k WHERE coalesce(k.spec->>'projection','') = '' AND EXISTS (SELECT 1 FROM project_documents d WHERE d.project_id = $1 AND d.entity_kind = k.name) AND true ORDER BY 1
